const lead = $json.body ?? $json;
const errors = [];

// Required: must have an email, and some content (text or an attachment)
if (!lead.from_email) errors.push('missing from_email');

const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(lead.from_email || '');
if (lead.from_email && !emailOk) errors.push('invalid email format');

const hasContent =
  (lead.raw_text && lead.raw_text.trim().length > 0) || lead.has_attachment === true;
if (!hasContent) errors.push('no message text or attachment');

// Idempotency key = fingerprint of (email + subject + today) to catch duplicates
const crypto = require('crypto');
const day = new Date().toISOString().slice(0, 10);
const keyBase = `${(lead.from_email || '').toLowerCase()}|${lead.subject || ''}|${day}`;
const idempotency_key = crypto.createHash('sha1').update(keyBase).digest('hex');

return {
  ...lead,
  valid: errors.length === 0,
  errors,
  idempotency_key,
};

// Original validated lead (keeps idempotency_key, source, contact info, etc.)
const original = $('If').item.json;

// The AI's raw text output (field name varies, so we check a few)
const raw = $json.output ?? $json.text ?? $json.response ?? '';
let cleaned = String(raw).trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();

let extracted;
let extraction_ok = true;
try {
  extracted = JSON.parse(cleaned);
} catch (e) {
  extraction_ok = false;            // fallback so a bad AI response never crashes the flow
  extracted = { doc_type: 'inquiry', message_summary: cleaned.slice(0, 200) };
}

// AI-derived fields first, original validated fields win for contact/keys
return { ...extracted, ...original, extraction_ok };

const lead = $json;
const CORE = new Set(['waterproofing', 'swimming_pools', 'landscape_design', 'building_works']);
const NEARBY = ['wah', 'taxila', 'murree', 'attock', 'gujar khan', 'kahuta', 'fateh jang'];

const sBudget = b => b == null ? 0 : b >= 500000 ? 25 : b >= 200000 ? 18 : b >= 50000 ? 10 : 4;
const sTimeline = d => d == null ? 0 : d <= 14 ? 20 : d <= 30 ? 14 : d <= 90 ? 8 : 3;
const sService = s => !s ? 0 : CORE.has(s) ? 20 : s === 'other' ? 5 : 0;
const sLocation = l => {
  if (!l) return 0;
  const x = String(l).toLowerCase();
  if (x.includes('islamabad') || x.includes('rawalpindi') || x.includes('pindi') || x.includes('isb')) return 15;
  if (NEARBY.some(c => x.includes(c))) return 8;
  return 3;
};
const sAuth = a => ({ yes: 10, unknown: 4, no: 0 }[String(a || 'unknown').toLowerCase()] ?? 4);
const sComplete = l => {
  let p = 0;
  for (const f of ['from_name', 'from_email', 'phone', 'budget_pkr', 'timeline_days']) {
    const v = l[f];
    if (v !== null && v !== undefined && v !== '' && !(Array.isArray(v) && v.length === 0)) p += 2;
  }
  return Math.min(p, 10);
};

const parts = {
  budget: sBudget(lead.budget_pkr),
  timeline: sTimeline(lead.timeline_days),
  service_match: sService(lead.service_requested),
  location: sLocation(lead.location),
  authority: sAuth(lead.decision_authority),
  completeness: sComplete(lead),
};
const total = Object.values(parts).reduce((a, b) => a + b, 0);
const qualification = total >= 70 ? 'HOT' : total >= 45 ? 'WARM' : 'NURTURE';
const score_reasons = Object.entries(parts).map(([k, v]) => `${k}: ${v} pts`).join(', ');

return { ...lead, score: total, qualification, score_reasons };

