const lead = $('Retrieve KB').item.json;   // full lead + score + kb
const raw = $json.output ?? $json.text ?? $json.response ?? '';
let cleaned = String(raw).trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();

let reply, reply_ok = true;
try {
  reply = JSON.parse(cleaned);
} catch (e) {
  reply_ok = false;
  reply = {
    ai_summary: lead.message_summary || '',
    fit_reason: '', risks: [], recommended_action: 'Manual review (AI output unparseable)',
    email_subject: 'Thanks for contacting Z&T',
    reply_body: 'Thank you for reaching out to Z&T. Our team will get back to you shortly.\n\nZ&T Team',
    sales_note: 'AI reply failed to parse - handle manually.',
  };
}

// flatten arrays for Airtable-friendly text
const risks = Array.isArray(reply.risks) ? reply.risks.join('; ') : (reply.risks || '');
return { ...lead, ...reply, risks, reply_ok };

// Knowledge base = Z&T's real services (retrieval by requested service)
const KB = {
  waterproofing: "Waterproofing: roof/basement/water-tank. PKR 60,000-400,000. Timeline 3 days-2 weeks. Area: Rawalpindi & Islamabad (travel charge beyond ~40km).",
  swimming_pools: "Swimming Pools: design + construction of residential pools. Starting ~PKR 1,500,000. Timeline 6-12 weeks.",
  landscape_design: "Landscape Design: gardens, lawns, hardscaping, irrigation. PKR 80,000-600,000. Timeline 2-6 weeks.",
  building_works: "Building Works: renovation, boundary walls, small construction. Quoted after a site visit.",
};
const POLICY = "Policy: minimum project value PKR 50,000. Free site survey within Rawalpindi/Islamabad. We do NOT offer: interior furniture, electrical rewiring, or plumbing-only jobs. Contact: WhatsApp +92 333 5158897, zahidkingpk@gmail.com.";

const lead = $json;
const section = KB[lead.service_requested] || "The requested service is NOT in our standard service list.";
const kb_context = `${section}\n${POLICY}`;
return { ...lead, kb_context };

